result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == LOWER('success'))) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

customer_success_rates = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    successful_transactions=COUNT(transactions_made.WHERE(LOWER(status) == 'success')),
    total_transactions=COUNT(transactions_made)
).CALCULATE(
    customer_name=customer_name,
    success_rate=100.0 * successful_transactions / total_transactions
).ORDER_BY(success_rate.ASC())

result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= '2023-01-01')
).PARTITION(
    name='country_groups', by=(country)
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)
